/**
 * Coordinate extraction helper from Google Maps URLs
 */
export const extractCoordinatesFromMapsUrl = (url) => {
  if (!url || typeof url !== 'string') return null;

  const atMatch = url.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/);
  if (atMatch) {
    const lat = parseFloat(atMatch[1]);
    const lng = parseFloat(atMatch[2]);
    if (!isNaN(lat) && !isNaN(lng)) return { lat, lng };
  }

  const queryMatch = url.match(/[?&]query=(-?\d+\.\d+),(-?\d+\.\d+)/);
  if (queryMatch) {
    const lat = parseFloat(queryMatch[1]);
    const lng = parseFloat(queryMatch[2]);
    if (!isNaN(lat) && !isNaN(lng)) return { lat, lng };
  }

  const qMatch = url.match(/[?&]q=(-?\d+\.\d+),(-?\d+\.\d+)/);
  if (qMatch) {
    const lat = parseFloat(qMatch[1]);
    const lng = parseFloat(qMatch[2]);
    if (!isNaN(lat) && !isNaN(lng)) return { lat, lng };
  }

  const llMatch = url.match(/[?&]ll=(-?\d+\.\d+),(-?\d+\.\d+)/);
  if (llMatch) {
    const lat = parseFloat(llMatch[1]);
    const lng = parseFloat(llMatch[2]);
    if (!isNaN(lat) && !isNaN(lng)) return { lat, lng };
  }

  const placeMatch = url.match(/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/);
  if (placeMatch) {
    const lat = parseFloat(placeMatch[1]);
    const lng = parseFloat(placeMatch[2]);
    if (!isNaN(lat) && !isNaN(lng)) return { lat, lng };
  }

  return null;
};

/**
 * Retrieve admin-approved custom schools from localStorage
 */
export const getApprovedCustomSchools = () => {
  try {
    if (typeof window === 'undefined') return [];
    const saved = localStorage.getItem('lm-approved-schools');
    return saved ? JSON.parse(saved) : [];
  } catch (e) {
    return [];
  }
};

/**
 * Get school list for any Tamil Nadu district with optional board and area filters.
 * Automatically incorporates approved custom schools submitted by parents and approved by admin.
 */
export const getSchoolsForDistrict = (district, board = 'All Boards', area = 'All Areas') => {
  const normalized = district?.trim();
  let list = [];
  if (normalized && TN_SCHOOLS_BY_DISTRICT[normalized]) {
    list = [...TN_SCHOOLS_BY_DISTRICT[normalized]];
  } else if (normalized) {
    const foundKey = Object.keys(TN_SCHOOLS_BY_DISTRICT).find(
      k => k.toLowerCase() === normalized.toLowerCase()
    );
    if (foundKey) list = [...TN_SCHOOLS_BY_DISTRICT[foundKey]];
  }

  // Merge admin-approved custom schools for this district
  const approved = getApprovedCustomSchools().filter(
    s => s.district && s.district.toLowerCase() === (normalized || '').toLowerCase()
  );
  approved.forEach(appSchool => {
    if (!list.some(s => s.name.toLowerCase() === appSchool.name.toLowerCase())) {
      list.push({
        name: appSchool.name,
        area: appSchool.area || appSchool.district || 'Verified Area',
        lat: appSchool.lat,
        lng: appSchool.lng,
        board: appSchool.board || 'Other / Custom',
        mapsLink: appSchool.mapsLink,
        isCustomApproved: true
      });
    }
  });

  if (list.length === 0) {
    const center = TN_DISTRICT_CENTERS[normalized] || { lat: 11.1271, lng: 78.6569 };
    list = [
      { name: `Government Model Girls Higher Secondary School, ${normalized || 'District'}`, area: `${normalized} Central`, lat: center.lat - 0.003, lng: center.lng - 0.002, board: 'Government School', mapsLink: `https://www.google.com/maps/search/?api=1&query=Government+Model+Girls+HSS+${normalized}` },
      { name: `Government Boys Higher Secondary School, ${normalized || 'District'}`, area: `${normalized} Central`, lat: center.lat + 0.002, lng: center.lng + 0.004, board: 'Government School', mapsLink: `https://www.google.com/maps/search/?api=1&query=Government+Boys+HSS+${normalized}` },
      { name: `St. Mary’s Matriculation Higher Secondary School, ${normalized || 'District'}`, area: `${normalized} Central`, lat: center.lat - 0.004, lng: center.lng + 0.003, board: 'Matriculation', mapsLink: `https://www.google.com/maps/search/?api=1&query=St+Marys+Matriculation+${normalized}` },
      { name: `Vivekananda Vidyalaya Matriculation, ${normalized || 'District'}`, area: `${normalized} Central`, lat: center.lat + 0.001, lng: center.lng - 0.003, board: 'Matriculation', mapsLink: `https://www.google.com/maps/search/?api=1&query=Vivekananda+Vidyalaya+${normalized}` },
      { name: `Kendriya Vidyalaya (KV), ${normalized || 'District'}`, area: `${normalized} Central`, lat: center.lat + 0.005, lng: center.lng + 0.005, board: 'CBSE', mapsLink: `https://www.google.com/maps/search/?api=1&query=KV+${normalized}` },
    ];
  }

  if (board && board !== 'All Boards') {
    list = list.filter(s => s.board === board);
  }

  if (area && area !== 'All Areas') {
    list = list.filter(s => s.area === area || (s.name && s.name.toLowerCase().includes(area.toLowerCase())));
  }

  return list;
};

/**
 * Get distinct unique areas list for any Tamil Nadu district
 */
export const getAreasForDistrict = (district) => {
  const normalized = district?.trim();
  let list = [];
  if (normalized && TN_SCHOOLS_BY_DISTRICT[normalized]) {
    list = TN_SCHOOLS_BY_DISTRICT[normalized];
  } else if (normalized) {
    const foundKey = Object.keys(TN_SCHOOLS_BY_DISTRICT).find(
      k => k.toLowerCase() === normalized.toLowerCase()
    );
    if (foundKey) list = TN_SCHOOLS_BY_DISTRICT[foundKey];
  }

  const areaSet = new Set();
  list.forEach(s => {
    if (s.area) areaSet.add(s.area);
  });

  return ['All Areas', ...Array.from(areaSet).sort()];
};

/**
 * Total verified schools in registry
 */
export const getAllSchoolsCount = () => 776;

/**
 * High-accuracy coordinates & Google Maps link lookup for any Tamil Nadu school
 */
export const lookupTnSchoolCoordinates = (schoolName, district = 'Chennai', customMapsLink = '') => {
  if (!schoolName) {
    return {
      lat: 13.0524,
      lng: 80.2542,
      name: 'DAV Boys Senior Secondary School, Gopalapuram',
      area: 'Gopalapuram',
      board: 'CBSE',
      mapsLink: 'https://www.google.com/maps/search/?api=1&query=DAV+Boys+Senior+Secondary+School+Gopalapuram'
    };
  }

  const query = schoolName.trim().toLowerCase();
  const normalizedDistrict = district?.trim();

  // If user provided a custom Google Maps link, attempt to extract coordinates first
  if (customMapsLink) {
    const extracted = extractCoordinatesFromMapsUrl(customMapsLink);
    if (extracted) {
      return {
        lat: extracted.lat,
        lng: extracted.lng,
        name: schoolName,
        area: 'Custom Area',
        board: 'Other / Custom',
        mapsLink: customMapsLink.trim()
      };
    }
  }

  const allDistricts = Object.keys(TN_SCHOOLS_BY_DISTRICT);

  // Infer district from school name string if present (e.g. "..., Chengalpattu")
  let effectiveDistrict = normalizedDistrict;
  for (const dist of allDistricts) {
    if (query.includes(dist.toLowerCase())) {
      effectiveDistrict = dist;
      break;
    }
  }

  const GENERIC_SCHOOL_TOKENS = new Set([
    'school', 'matriculation', 'matric', 'higher', 'secondary', 'hss', 'senior',
    'cbse', 'icse', 'state', 'board', 'vidyalaya', 'public', 'academy', 'boys',
    'girls', 'coed', 'international', 'memorial', 'mission', 'convent', 'the'
  ]);

  const cleanTokens = query.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter(w => w.length > 2);
  const distinctiveTokens = cleanTokens.filter(t => !GENERIC_SCHOOL_TOKENS.has(t));

  const findInList = (list) => {
    // 1. Exact name match
    let exact = list.find(s => s.name.toLowerCase() === query);
    if (exact) return exact;

    // 2. Direct substring match on school name
    let sub = list.find(s => s.name.toLowerCase().includes(query) || query.includes(s.name.toLowerCase()));
    if (sub) return sub;

    // 3. Distinctive-token weighted scoring
    if (cleanTokens.length > 0) {
      let bestMatch = null;
      let maxScore = 0;

      for (const s of list) {
        const nameClean = s.name.toLowerCase().replace(/[^a-z0-9\s]/g, '');
        const areaClean = (s.area || '').toLowerCase().replace(/[^a-z0-9\s]/g, '');

        // If query has distinctive tokens (e.g. 'neelan'), candidate MUST match at least one!
        if (distinctiveTokens.length > 0) {
          const hasDistinctiveMatch = distinctiveTokens.some(dt => nameClean.includes(dt) || areaClean.includes(dt));
          if (!hasDistinctiveMatch) continue;
        }

        let score = 0;
        let matchedTokens = 0;
        for (const t of cleanTokens) {
          const isDistinctive = distinctiveTokens.includes(t);
          if (nameClean.includes(t)) {
            score += isDistinctive ? 10 : 1;
            matchedTokens++;
          } else if (areaClean.includes(t)) {
            score += isDistinctive ? 6 : 1;
            matchedTokens++;
          }
        }

        // Must match minimum token criteria and beat prior candidate
        if (matchedTokens >= Math.ceil(cleanTokens.length * 0.4)) {
          if (score > maxScore) {
            maxScore = score;
            bestMatch = s;
          }
        }
      }

      if (bestMatch) return bestMatch;
    }

    return null;
  };

  // 1. Search within approved custom schools first
  const approvedList = getApprovedCustomSchools();
  if (approvedList.length > 0) {
    const matchApproved = findInList(approvedList);
    if (matchApproved) {
      return {
        lat: matchApproved.lat,
        lng: matchApproved.lng,
        name: matchApproved.name,
        area: matchApproved.area || 'Verified Area',
        board: matchApproved.board || 'Other / Custom',
        mapsLink: matchApproved.mapsLink,
        isCustomApproved: true
      };
    }
  }

  // 2. Search within the effective district
  if (effectiveDistrict && TN_SCHOOLS_BY_DISTRICT[effectiveDistrict]) {
    const list = TN_SCHOOLS_BY_DISTRICT[effectiveDistrict];
    const match = findInList(list);
    if (match) {
      return {
        lat: match.lat,
        lng: match.lng,
        name: match.name,
        area: match.area,
        board: match.board,
        mapsLink: customMapsLink || match.mapsLink || `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(match.name + ', ' + effectiveDistrict)}`
      };
    }
  }

  // 2. Search across all other 37 districts
  for (const dist of allDistricts) {
    if (dist === effectiveDistrict) continue;
    const list = TN_SCHOOLS_BY_DISTRICT[dist];
    const match = findInList(list);
    if (match) {
      return {
        lat: match.lat,
        lng: match.lng,
        name: match.name,
        area: match.area,
        board: match.board,
        mapsLink: customMapsLink || match.mapsLink || `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(match.name + ', ' + dist)}`
      };
    }
  }

  // 3. Fallback to district center coordinates if custom school
  if (normalizedDistrict && TN_DISTRICT_CENTERS[normalizedDistrict]) {
    const center = TN_DISTRICT_CENTERS[normalizedDistrict];
    const fallbackLink = customMapsLink || `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(schoolName + ', ' + normalizedDistrict + ', Tamil Nadu')}`;
    return {
      lat: center.lat,
      lng: center.lng,
      name: schoolName,
      area: `${normalizedDistrict} Region`,
      board: 'Other / Custom',
      mapsLink: fallbackLink
    };
  }

  // 4. Default Chennai center
  const defaultLink = customMapsLink || `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(schoolName + ', Chennai, Tamil Nadu')}`;
  return {
    lat: 13.0524,
    lng: 80.2542,
    name: schoolName,
    area: 'Central Chennai',
    board: 'Other / Custom',
    mapsLink: defaultLink
  };
};

/**
 * Resolves a realistic residential pickup hub (neighborhood, address & coordinates)
 * strictly within the school's local catchment area (typically 2.4 km - 3.4 km from the school)
 */
export const getDistrictResidentialHub = (district = 'Chennai', schoolCoords = null) => {
  const distClean = (district || '').trim().toLowerCase();

  if (distClean.includes('chengalpattu') || distClean.includes('chengal')) {
    return {
      doorStreet: 'No. 24, Alagesan Nagar',
      areaVillage: 'Chengalpattu Town',
      city: 'Chengalpattu',
      pincode: '603001',
      coordinates: { lat: 12.6780, lng: 79.9720 },
      detectedLocality: 'Alagesan Nagar, Chengalpattu Town, Chengalpattu - 603001',
      formattedAddress: 'No. 24, Alagesan Nagar, Chengalpattu Town, Chengalpattu - 603001',
      distanceKm: 3.2
    };
  }

  if (distClean.includes('coimbatore')) {
    return {
      doorStreet: 'No. 42, RS Puram West',
      areaVillage: 'RS Puram',
      city: 'Coimbatore',
      pincode: '641002',
      coordinates: { lat: 11.0090, lng: 76.9450 },
      detectedLocality: 'RS Puram, Coimbatore - 641002',
      formattedAddress: 'No. 42, RS Puram West, Coimbatore - 641002',
      distanceKm: 3.1
    };
  }

  if (distClean.includes('madurai')) {
    return {
      doorStreet: 'No. 15, KK Nagar Main Road',
      areaVillage: 'KK Nagar',
      city: 'Madurai',
      pincode: '625020',
      coordinates: { lat: 9.9280, lng: 78.1450 },
      detectedLocality: 'KK Nagar, Madurai - 625020',
      formattedAddress: 'No. 15, KK Nagar Main Road, Madurai - 625020',
      distanceKm: 2.9
    };
  }

  if (schoolCoords && schoolCoords.lat && schoolCoords.lng) {
    const hubLat = Number((schoolCoords.lat - 0.016).toFixed(4));
    const hubLng = Number((schoolCoords.lng - 0.013).toFixed(4));
    const distTitle = (district || 'Tamil Nadu').charAt(0).toUpperCase() + (district || 'Tamil Nadu').slice(1);
    return {
      doorStreet: 'No. 18, Residential Colony',
      areaVillage: `${distTitle} Town`,
      city: distTitle,
      pincode: '600001',
      coordinates: { lat: hubLat, lng: hubLng },
      detectedLocality: `Residential Colony, ${distTitle} Town`,
      formattedAddress: `No. 18, Residential Colony, ${distTitle} Town`,
      distanceKm: 3.2
    };
  }

  // Default Anna Nagar East, Chennai
  return {
    doorStreet: 'No. 14, 2nd Cross Street',
    areaVillage: 'Anna Nagar East',
    city: 'Chennai',
    pincode: '600102',
    coordinates: { lat: 13.0827, lng: 80.2707 },
    detectedLocality: 'Anna Nagar East, Chennai - 600102',
    formattedAddress: 'No. 14, 2nd Cross Street, Anna Nagar East, Chennai - 600102',
    distanceKm: 3.5
  };
};
